package com.agrolink.controller;import com.agrolink.dto.ai.*;import com.agrolink.service.AiService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ai") public class AiController{private final AiService s;public AiController(AiService s){this.s=s;}@PostMapping("/crop-prediction") public CropPredictionResponse crop(@Valid @RequestBody CropPredictionRequest r){return s.crop(r);}@PostMapping("/demand-prediction") public DemandPredictionResponse demand(@Valid @RequestBody DemandPredictionRequest r){return s.demand(r);}@PostMapping("/yield-prediction") public YieldPredictionResponse yield(@Valid @RequestBody YieldPredictionRequest r){return s.yield(r);}@PostMapping("/chat") public ChatResponse chat(@RequestBody java.util.Map<String,String> body){String question=body==null?null:body.get("question");if(question==null||question.isBlank())throw new IllegalArgumentException("Question is required");return s.chat(new ChatRequest(question));}}
